// Runtime narrowing for untrusted URL strings. Wire strings themselves are generated by Rust.

import type { AssignmentReference } from "../../generated/api/AssignmentReference";
import type { CourseInstanceReference } from "../../generated/api/CourseInstanceReference";
import type { CourseMembershipReference } from "../../generated/api/CourseMembershipReference";
import type { QuestionId } from "../../generated/api/QuestionId";
import type { AssignmentAttemptReference } from "../../generated/api/AssignmentAttemptReference";
import type { AuthoringWorkspaceReference } from "../../generated/api/AuthoringWorkspaceReference";
import { normalizeQuestionIdSyntax } from "../question_id";

declare const routeReferenceBrand: unique symbol;
type BrandedRouteReference<Kind extends string> = string & { readonly [routeReferenceBrand]: Kind };
export type CourseRouteReference = CourseInstanceReference & BrandedRouteReference<"course">;
export type CourseMembershipRouteReference = CourseMembershipReference &
  BrandedRouteReference<"courseMembership">;
export type AssignmentRouteReference = AssignmentReference & BrandedRouteReference<"assignment">;
export type AssignmentAttemptRouteReference = AssignmentAttemptReference &
  BrandedRouteReference<"assignmentAttempt">;
export type WorkspaceRouteReference = AuthoringWorkspaceReference &
  BrandedRouteReference<"workspace">;
export type QuestionRouteReference = BrandedRouteReference<"question">;
export type PublicRouteReference =
  | AssignmentAttemptRouteReference
  | CourseRouteReference
  | AssignmentRouteReference
  | WorkspaceRouteReference;

function parseExact<Kind extends string>(
  value: string,
  prefix: string,
): BrandedRouteReference<Kind> | null {
  if (!new RegExp(`^${prefix}-[1-9][0-9]{0,9}$`, "u").test(value)) return null;
  const number = Number(value.slice(prefix.length + 1));
  return Number.isSafeInteger(number) && number <= 2_147_483_647
    ? (value as BrandedRouteReference<Kind>)
    : null;
}
export function parseCourseReference(value: string): CourseRouteReference | null {
  return parseExact<"course">(value, "C");
}
export function parseCourseMembershipReference(
  value: string,
): CourseMembershipRouteReference | null {
  return parseExact<"courseMembership">(value, "M");
}
export function parseAssignmentReference(value: string): AssignmentRouteReference | null {
  return parseExact<"assignment">(value, "A");
}
export function parseAssignmentAttemptReference(
  value: string,
): AssignmentAttemptRouteReference | null {
  return parseExact<"assignmentAttempt">(value, "R");
}
export function parseWorkspaceReference(value: string): WorkspaceRouteReference | null {
  return parseExact<"workspace">(value, "W");
}
export function courseRouteReference(value: CourseInstanceReference): CourseRouteReference {
  const result = parseCourseReference(value);
  if (result === null) throw new Error("invalid course reference");
  return result;
}
export function assignmentRouteReference(value: AssignmentReference): AssignmentRouteReference {
  const result = parseAssignmentReference(value);
  if (result === null) throw new Error("invalid assignment reference");
  return result;
}
export function courseMembershipRouteReference(
  value: CourseMembershipReference,
): CourseMembershipRouteReference {
  const result = parseCourseMembershipReference(value);
  if (result === null) throw new Error("invalid course membership reference");
  return result;
}
export function assignmentAttemptRouteReference(
  value: AssignmentAttemptReference,
): AssignmentAttemptRouteReference {
  const result = parseAssignmentAttemptReference(value);
  if (result === null) throw new Error("invalid Assignment Attempt reference");
  return result;
}
export function authoringWorkspaceRouteReference(
  value: AuthoringWorkspaceReference,
): WorkspaceRouteReference {
  const result = parseWorkspaceReference(value);
  if (result === null) throw new Error("invalid workspace reference");
  return result;
}
export function parsePublicRouteReference(value: string): PublicRouteReference | null {
  return (
    parseCourseReference(value) ??
    parseAssignmentReference(value) ??
    parseAssignmentAttemptReference(value) ??
    parseWorkspaceReference(value)
  );
}
export function questionRouteReference(questionId: QuestionId): QuestionRouteReference {
  const result = parseQuestionRouteReference(questionId);
  if (result === null) throw new Error("question ID must use Crockford Base32");
  return result;
}
export function parseQuestionRouteReference(value: string): QuestionRouteReference | null {
  return normalizeQuestionIdSyntax(value) as QuestionRouteReference | null;
}
